</span></span><span style="display:flex;"><span> <span style="color:#ff636f">if</span> (<span style="color:#58a1dd">oldrev</span> <span style="color:#ff636f">==</span> <span style="color:#58a1dd">zerooid</span>) {
</span></span><span style="display:flex;"><span> <span style="color:#ff636f">return</span> <span style="color:#58a1dd">ExecuteTreeWalk</span>(<span style="color:#58a1dd">newrev</span>);
</span></span><span style="display:flex;"><span> }
</span></span><span style="display:flex;"><span> <span style="color:#ff636f">if</span> (<span style="color:#58a1dd">newrev</span> <span style="color:#ff636f">==</span> <span style="color:#58a1dd">zerooid</span>) {
</span></span><span style="display:flex;"><span> <span style="color:#ff636f">return</span> <span style="color:#58a1dd">ExecuteTreeWalk</span>(<span style="color:#58a1dd">oldrev</span>);
</span></span><span style="display:flex;"><span> }
</span></span><span style="display:flex;"><span> <span style="color:#58a1dd">git_oid</span> <span style="color:#58a1dd">ooid</span>, <span style="color:#58a1dd">noid</span>;
</span></span><span style="display:flex;"><span> <span style="color:#ff636f">if</span> (<span style="color:#58a1dd">git_oid_fromstrn</span>(<span style="color:#ff636f">&amp;</span><span style="color:#58a1dd">ooid</span>, <span style="color:#58a1dd">oldrev</span>.<span style="color:#58a1dd">data</span>(), <span style="color:#58a1dd">oldrev</span>.<span style="color:#58a1dd">size</span>()) <span style="color:#ff636f">!=</span> <span style="color:#a6be9d">0</span>) {
</span></span><span style="display:flex;"><span> <span style="color:#ff636f">return</span> <span style="color:#58a1dd">false</span>;
</span></span><span style="display:flex;"><span> }
